 	return s.proxyHandler.DynamicProxy(func(r *http.Request) (string, error) {
 		sess, err := s.sessionManager.GetOrCreate(r, nil)
 		if err != nil {
 			return "", fmt.Errorf("failed to get session: %w", err)
