 			StartTimeout:  time.Duration(cfg.Graph.StartTimeout) * time.Second,
 			StopTimeout:   time.Duration(cfg.Graph.StopTimeout) * time.Second,
 			Stdout:        logging.NewSubprocessWriter("knirvgraph", os.Stdout),
